import * as React from "react"
import { createPortal } from "react-dom"
// Standalone Framer Shim for Next.js / React
const useIsStaticRenderer = () => false;
const addPropertyControls = () => {};
const ControlType = {
    Boolean: 'boolean', Number: 'number', String: 'string',
    Color: 'color', Enum: 'enum', Object: 'object',
    Array: 'array', Image: 'image', ResponsiveImage: 'responsiveImage',
    Font: 'font', Transition: 'transition', Link: 'link'
};


/* ============================================================================
 * AccessibilityDeck — Accessibility preferences deck for Framer
 * ----------------------------------------------------------------------------
 * 18 tools, 7 one-tap profiles, page navigator, read-aloud with sentence
 * tracking, draggable persistent launcher, full keyboard support.
 *
 * Architecture note: the UI is portalled OUTSIDE <body> (as a child of <html>)
 * so that page-wide CSS filters (contrast / invert / grayscale / colour-vision)
 * can be applied to <body> without ever tinting the deck itself. This avoids
 * the backdrop-filter fragility of most accessibility widgets.
 * ========================================================================== */

/* ---------------------------------- types --------------------------------- */

type Contrast = "off" | "dark" | "light" | "invert" | "boost"
type Saturate = "off" | "low" | "gray" | "high"
type Vision = "off" | "prot" | "deut" | "trit"
type Typeface = "off" | "legible" | "dyslexic"

interface Prefs {
    textScale: number
    spacing: number
    typeface: Typeface
    alignLeft: boolean
    contrast: Contrast
    saturate: Saturate
    vision: Vision
    warm: boolean
    highlightLinks: boolean
    highlightTitles: boolean
    focusRing: boolean
    bigCursor: boolean
    mask: boolean
    guide: boolean
    hideImages: boolean
    stopMotion: boolean
}

const DEFAULTS: Prefs = {
    textScale: 1,
    spacing: 0,
    typeface: "off",
    alignLeft: false,
    contrast: "off",
    saturate: "off",
    vision: "off",
    warm: false,
    highlightLinks: false,
    highlightTitles: false,
    focusRing: false,
    bigCursor: false,
    mask: false,
    guide: false,
    hideImages: false,
    stopMotion: false,
}

