function matchProfile(current: Prefs): string | null {
    const keys = Object.keys(DEFAULTS) as PrefKey[]
    const hit = PROFILES.find((pr) => {
        const target: any = { ...DEFAULTS, ...pr.patch }
        return keys.every((k) => current[k] === target[k])
    })
    return hit ? hit.id : null
}

/* --------------------------------- helpers -------------------------------- */

const isBrowser = () =>
    typeof window !== "undefined" && typeof document !== "undefined"

function clamp(n: number, min: number, max: number) {
    return Math.min(max, Math.max(min, n))
}

function safeRead<T>(key: string, fallback: T): T {
    if (!isBrowser()) return fallback
    try {
        const raw = window.localStorage.getItem(key)
        if (!raw) return fallback
        return { ...(fallback as any), ...JSON.parse(raw) } as T
    } catch {
        return fallback
    }
}

function safeWrite(key: string, value: unknown) {
    if (!isBrowser()) return
    try {
        window.localStorage.setItem(key, JSON.stringify(value))
    } catch {
        /* quota or privacy mode — silently ignore */
    }
}

function hexToRgb(hex: string): [number, number, number] {
    const h = (hex || "").replace("#", "").trim()
    if (h.length === 3) {
        return [
            parseInt(h[0] + h[0], 16),
            parseInt(h[1] + h[1], 16),
            parseInt(h[2] + h[2], 16),
        ]
    }
    if (h.length >= 6) {
        return [
            parseInt(h.slice(0, 2), 16),
            parseInt(h.slice(2, 4), 16),
            parseInt(h.slice(4, 6), 16),
        ]
    }
    return [79, 70, 229]
}

function alpha(hex: string, a: number) {
    const [r, g, b] = hexToRgb(hex)
    return `rgba(${r},${g},${b},${a})`
}

function readableOn(hex: string) {
    const [r, g, b] = hexToRgb(hex)
    const l = (0.299 * r + 0.587 * g + 0.114 * b) / 255
    return l > 0.62 ? "#0b0b10" : "#ffffff"
}

/* WCAG relative luminance and contrast ratio (1.4.3 / 1.4.11). */
function luminance(hex: string) {
    const c = hexToRgb(hex).map((v) => {
        const s = v / 255
        return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4)
    })
    return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2]
}

function contrastRatio(a: string, b: string) {
    const la = luminance(a)
    const lb = luminance(b)
    return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05)
}

function shiftHex(hex: string, amount: number) {
    const [r, g, b] = hexToRgb(hex)
    const f = (v: number) =>
        Math.round(
            clamp(
                amount > 0 ? v + (255 - v) * amount : v * (1 + amount),
                0,
                255
            )
        )
    return (
        "#" +
        [f(r), f(g), f(b)].map((v) => v.toString(16).padStart(2, "0")).join("")
    )
}

/**
 * Darkens or lightens the author's accent until it clears 4.5:1 against the
 * panel background, so a pale brand colour can never produce unreadable text.
 * Used only where accent is a TEXT colour; fills and borders keep the original.
 */
function accentTextFor(accent: string, bg: string) {
    const towardsLight = luminance(bg) < 0.4
    let out = accent
    for (let i = 0; i < 24 && contrastRatio(out, bg) < 4.5; i++) {
        out = shiftHex(out, towardsLight ? 0.09 : -0.09)
    }
    return out
}

/* ------------------------- page-wide CSS generation ----------------------- */

function buildCSS(p: Prefs, accent: string, maskHeight: number): string {
    const out: string[] = []

    /* --- composited body filter (contrast / saturation / vision / warmth) -- */
    const filters: string[] = []
    if (p.contrast === "dark" || p.contrast === "invert")
        filters.push("invert(1) hue-rotate(180deg)")
    if (p.contrast === "boost") filters.push("contrast(1.35)")
    if (p.saturate === "gray") filters.push("grayscale(1)")
    if (p.saturate === "low") filters.push("saturate(0.5)")
    if (p.saturate === "high") filters.push("saturate(1.6)")
    if (p.warm) filters.push("sepia(0.32) saturate(1.15) hue-rotate(-8deg)")
    if (p.vision !== "off") filters.push(`url(#a11y-cv-${p.vision})`)

    if (filters.length) {
        out.push(`body{filter:${filters.join(" ")} !important;}`)
    }
    if (p.contrast === "dark" || p.contrast === "invert") {
        out.push(
            `body :where(img,picture,video,canvas,iframe,[style*="background-image"]){filter:invert(1) hue-rotate(180deg) !important;}`
        )
    }

    /* -------------------------------- text size ----------------------------
     * A single declaration on the page root rather than a DOM walk writing
     * inline font sizes. `zoom` is the only CSS mechanism that scales text
     * proportionally from each element's own size: `em` resolves against the
     * parent, so it would flatten headings and body copy toward each other.
     * The panel is unaffected because it renders outside <body>.
     * ---------------------------------------------------------------------- */
    if (p.textScale !== 1) {
        out.push(`body{zoom:${p.textScale} !important;}`)
    }

    /* ------------------------------- typography ---------------------------- */
    if (p.typeface === "dyslexic") {
        out.push(
            `@font-face{font-family:"A11y OpenDyslexic";font-display:swap;font-weight:400;src:url(data:font/woff2;base64,${FONT_OD_400}) format("woff2");}`,
            `@font-face{font-family:"A11y OpenDyslexic";font-display:swap;font-weight:700;src:url(data:font/woff2;base64,${FONT_OD_700}) format("woff2");}`,
            `body,body *:not(svg):not(path){font-family:"A11y OpenDyslexic","Comic Sans MS",Verdana,sans-serif !important;}`
        )
    } else if (p.typeface === "legible") {
        out.push(
            `@font-face{font-family:"A11y Hyperlegible";font-display:swap;font-weight:400;src:url(data:font/woff2;base64,${FONT_AH_400}) format("woff2");}`,
            `@font-face{font-family:"A11y Hyperlegible";font-display:swap;font-weight:700;src:url(data:font/woff2;base64,${FONT_AH_700}) format("woff2");}`,
            `body,body *:not(svg):not(path){font-family:"A11y Hyperlegible",Verdana,Tahoma,sans-serif !important;}`
        )
    }

    if (p.spacing > 0) {
        const s = SPACING_STEPS[clamp(p.spacing, 0, 3)]
        out.push(
            `body :where(p,li,a,span,h1,h2,h3,h4,h5,h6,td,th,dd,dt,blockquote,figcaption,label,button,input,textarea){line-height:${s.lh} !important;letter-spacing:${s.ls}em !important;word-spacing:${s.ws}em !important;}`
        )
    }

    if (p.alignLeft) {
        out.push(
            `body :where(p,li,h1,h2,h3,h4,h5,h6,blockquote,figcaption,td,th,dd,dt){text-align:left !important;text-justify:none !important;}`
        )
    }

    /* --------------------------------- links ------------------------------- */
    if (p.highlightLinks) {
        out.push(
            `body a{text-decoration:underline !important;text-underline-offset:3px !important;text-decoration-thickness:2px !important;outline:2px solid ${accent} !important;outline-offset:2px !important;border-radius:2px;}`,
            `body a:hover{background:${alpha(accent, 0.18)} !important;}`
        )
    }
    if (p.highlightTitles) {
        out.push(
            `body :where(h1,h2,h3,h4,h5,h6){background:${alpha(accent, 0.12)} !important;box-shadow:inset 4px 0 0 ${accent} !important;padding-left:10px !important;}`
        )
    }

    /* ------------------------------ focus ring ----------------------------- */
    if (p.focusRing) {
        out.push(
            `body *:focus,body *:focus-visible{outline:4px solid ${accent} !important;outline-offset:3px !important;box-shadow:0 0 0 8px ${alpha(accent, 0.28)} !important;border-radius:3px;scroll-margin:96px;}`
        )
    }

    /* ------------------------------ big cursor ----------------------------- */
    if (p.bigCursor) {
        const cur = encodeURIComponent(
            `<svg xmlns="http://www.w3.org/2000/svg" width="52" height="52" viewBox="0 0 52 52"><path d="M8 4 L8 42 L18 32 L25 47 L33 43 L26 28 L40 28 Z" fill="#fff" stroke="#000" stroke-width="3" stroke-linejoin="round"/></svg>`
        )
        out.push(
            `body,body *{cursor:url("data:image/svg+xml,${cur}") 6 4,auto !important;}`,
            `body a,body button,body [role="button"],body input,body select,body textarea{cursor:url("data:image/svg+xml,${cur}") 6 4,pointer !important;}`
        )
    }

    /* ------------------------------ hide images ---------------------------- */
    if (p.hideImages) {
        out.push(
            /* Scoped to media elements. A blanket background-image rule across
               every element would strip decorative backgrounds other components
               depend on, and injecting pseudo-element content risks overwriting
               theirs. */
            `body :where(img,picture,video,canvas,iframe,object,embed){visibility:hidden !important;}`
        )
    }

    /* ------------------------------ stop motion ---------------------------- */
    if (p.stopMotion) {
        out.push(
            /* Pauses running animation without zeroing durations or killing
               transitions outright, so interactive components still respond. */
            `body *,body *::before,body *::after{animation-play-state:paused !important;}`,
            `html,body{scroll-behavior:auto !important;}`,
            `body :where(marquee){-webkit-animation:none !important;animation:none !important;}`
        )
    }

    /* ----------------------------- read-aloud cue -------------------------- */
    out.push(`::highlight(a11y-read){background-color:${alpha(accent, 0.28)};}`)

    /* ------------------------------ reading mask --------------------------- */
    if (p.mask) {
        out.push(`html{--a11y-mask-h:${maskHeight}px;}`)
    }

    return out.join("\n")
}

/* --------------------------- text-scaling engine --------------------------
 * Scaling is applied as a single CSS declaration on the page root rather than
 * by walking the DOM and writing inline font sizes. Nothing is queried, no
 * attributes are attached, and removing the stylesheet restores the page
 * exactly. The panel is unaffected because it renders outside <body>.
 * ------------------------------------------------------------------------ */

